<script setup lang="ts">defineProps<{data:any}>();function label(s:string){return s.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase())}</script>
<template><div class="data-panel"><template v-if="Array.isArray(data)"><p v-if="!data.length" class="muted">No entries yet.</p><div v-for="(row,index) in data" :key="index" class="data-row"><DataPanel :data="row"/></div></template><dl v-else-if="data&&typeof data==='object'" class="data-grid"><template v-for="(value,key) in data" :key="key"><template v-if="!['source','region','document_version_id'].includes(String(key))"><div v-if="value!==null" :class="typeof value==='object'?'data-wide':''"><dt>{{label(String(key))}}</dt><dd><DataPanel v-if="typeof value==='object'" :data="value"/><span v-else>{{value}}</span></dd></div></template></template></dl><span v-else>{{data}}</span></div></template>
